const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.contentHistory)) staticData.contentHistory = [];
if (!Number.isInteger(staticData.categoryIndex)) staticData.categoryIndex = 0;

const categories = ['science','space','animals','human body','psychology','history','technology','nature','geography','inventions','food origins','language','money and economics','mysteries and unusual facts','records and comparisons','ocean','weather and natural phenomena','everyday objects','transportation','art and culture'];

const start = staticData.categoryIndex % categories.length;
const chosen = Array.from({length:10}, (_,i)=>categories[(start+i)%categories.length]);
const history = staticData.contentHistory.slice(-120);
const previous = history.length ? history.map((x,i)=>`${i+1}. CATEGORY: ${x.category}
TITLE: ${x.title}
HOOK: ${x.hook}
TOPIC: ${x.topic}`).join('
') : 'No previous content exists yet.';

const output=[];

for(let i=0;i<10;i++) {
  const category=chosen[i];
  const system=`You are an expert viral YouTube Shorts scriptwriter.

The channel publishes surprising, accurate and verifiable "Did You Know?" facts.

ASSIGNED CATEGORY: ${category}

Return ONLY one JSON object with EXACTLY these keys:

hook - one short pattern-interrupt sentence and the first line of the narration.
script - FULL English narration, 70-90 words. Start with the hook. Conversational, fast and punchy. ONE strong fact. End with a short question or follow-for-more line. No emojis, hashtags or stage directions.
subtitle_ar - natural Modern Standard Arabic translation of the COMPLETE narration, preserving the same meaning and order for on-screen subtitles.
title - maximum 90 characters and MUST end with " #Shorts".
description - 2-3 natural English sentences followed by a new line with 5 relevant hashtags.
tags - array of 8-12 lowercase English keyword strings.
query - 1-2 word English stock-video search query matching the topic.
topic - concise description of the core fact.
category - exactly the assigned category.

RULES:
1. The fact must be verifiable. Never invent statistics or fake historical claims.
2. Never reuse a previous fact or make a near-copy.
3. Never reuse or closely imitate a previous title or hook.
4. Stay inside the assigned category.
5. Make it easy to understand in under one minute.
6. One strong fact per video.
7. Keep the script suitable for roughly 35-55 seconds.
8. Make the hook immediately interesting.
9. The Arabic subtitle must be a complete natural translation, not a summary.
10. Do not include Arabic text in title, description, tags or query.

PREVIOUS CONTENT TO AVOID:
${previous}`;

  output.push({json:{
    batchNumber:i+1,
    category,
    body:{
      model:'llama-3.3-70b-versatile',
      temperature:1.05,
      response_format:{type:'json_object'},
      messages:[
        {role:'system',content:system},
        {role:'user',content:`Generate ONE completely fresh ${category} Short. Return JSON only.`}
      ]
    }
  }});
}

staticData.categoryIndex=(start+10)%categories.length;
return output;

const out=[];
for(const inputItem of $input.all()){
  const res=inputItem.json;
  const content=res.choices?.[0]?.message?.content;
  if(!content) throw new Error('No content from Groq: '+JSON.stringify(res).slice(0,1000));

  let data;
  try{data=JSON.parse(content);}catch(e){throw new Error('Groq did not return valid JSON: '+content.slice(0,1000));}

  for(const key of ['script','title','hook','topic','subtitle_ar']) if(!data[key]) throw new Error(`Groq JSON missing ${key}`);

  if(!String(data.subtitle_ar).trim()) throw new Error('Groq returned empty Arabic subtitle');

  data.tags=Array.isArray(data.tags)?data.tags:[];
  data.query=String(data.query||'abstract').trim();
  data.category=data.category||inputItem.json.category||'general';

  data.voice='af_bella';
  data.speed=1.0;
  data.lang='en-us';
  data.music=true;
  data.music_volume=0.10;
  data.animation=true;
  data.ads=false;

  let titleBase=String(data.title).replace(/\s*#shorts\s*$/i,'').trim();
  if(!titleBase) throw new Error('Empty title');
  if(titleBase.length>82) titleBase=titleBase.slice(0,82).replace(/\s+\S*$/,'');
  data.title=titleBase+' #Shorts';

  const wc=String(data.script).trim().split(/\s+/).filter(Boolean).length;
  if(wc<65||wc>100) throw new Error(`SCRIPT_LENGTH_REJECTED: ${wc} words for batch ${inputItem.json.batchNumber}.`);

  out.push({json:{...data,batchNumber:inputItem.json.batchNumber,requestedCategory:inputItem.json.category}});
}
return out;

const staticData=$getWorkflowStaticData('global');
if(!Array.isArray(staticData.contentHistory)) staticData.contentHistory=[];
function normalize(t){return String(t||'').toLowerCase().replace(/#shorts/g,'').replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();}
function words(t){return new Set(normalize(t).split(' ').filter(w=>w.length>3));}
function similarity(a,b){const A=words(a),B=words(b);if(!A.size||!B.size)return 0;let n=0;for(const w of A)if(B.has(w))n++;return n/Math.max(1,Math.min(A.size,B.size));}
const prior=staticData.contentHistory.slice(-120),accepted=[],out=[];
for(const inputItem of $input.all()){
  const item=inputItem.json;
  const candidate=[item.title,item.hook,item.topic,item.script].join(' ');

  if(item.category!==item.requestedCategory) throw new Error(`CATEGORY_MISMATCH: batch ${item.batchNumber}`);

  for(const old of [...prior,...accepted]){
    if(normalize(item.title)===normalize(old.title)) throw new Error(`DUPLICATE_CONTENT_REJECTED: batch ${item.batchNumber}: duplicate title`);
    if(normalize(item.hook)===normalize(old.hook)) throw new Error(`DUPLICATE_CONTENT_REJECTED: batch ${item.batchNumber}: duplicate hook`);
    if(similarity(item.topic,old.topic)>=0.60) throw new Error(`DUPLICATE_CONTENT_REJECTED: batch ${item.batchNumber}: very similar topic`);
    if(similarity(candidate,[old.title,old.hook,old.topic,old.script].join(' '))>=0.58) throw new Error(`DUPLICATE_CONTENT_REJECTED: batch ${item.batchNumber}: very similar content`);
  }

  accepted.push({title:item.title,hook:item.hook,topic:item.topic,script:item.script,query:item.query,category:item.category,createdAt:new Date().toISOString()});
  out.push({json:item});
}

for(const x of accepted) prior.push(x);
while(prior.length>120) prior.shift();
staticData.contentHistory=prior;
return out;

const out=[];
for(const inputItem of $input.all()){
  const item=inputItem.json;
  const runId=`${String($execution.id||Date.now())}_${item.batchNumber}`;
  const runDir=`/data/${runId}`;

  const job={
    script:item.script,
    voice:'af_bella',
    speed:1.0,
    lang:'en-us',
    music:true,
    music_volume:0.10,
    animation:true,
    ads:false,
    scenes:[
      {
        text_en:item.script,
        text_ar:item.subtitle_ar,
        pexels_query:item.query
      }
    ]
  };

  const jobB64=Buffer.from(JSON.stringify(job),'utf8').toString('base64');

  out.push({json:{
    runId,
    runDir,
    jobB64,
    title:item.title,
    description:item.description||'',
    tags:item.tags,
    topic:item.topic,
    category:item.category,
    batchNumber:item.batchNumber
  }});
}
return out;
